@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public Order getOrder(@PathVariable Long id) {
        // Client sends Accept: application/json → Jackson converts Order to JSON
        // Client sends Accept: application/xml → JAXB converts Order to XML
        return new Order(id, "Laptop", 1299.99);
    }

    @PostMapping(consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        // Content-Type: application/json tells Spring to use Jackson to parse body
        var saved = orderService.save(order);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }
}

record Order(Long id, String item, Double price) {}

@RestController
@RequestMapping("/api/products")
public class ProductController {

    @GetMapping(value = "/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
    public Product getProductJson(@PathVariable Long id) {
        // Only accepts requests with Accept: application/json
        return productService.findById(id);
    }

    @GetMapping(value = "/{id}/xml", produces = MediaType.APPLICATION_XML_VALUE)
    public Product getProductXml(@PathVariable Long id) {
        // Only accepts requests with Accept: application/xml
        return productService.findById(id);
    }

    @PostMapping(
        consumes = MediaType.APPLICATION_JSON_VALUE,
        produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<Product> createProduct(@RequestBody Product product) {
        // consumes: only accepts JSON request body (checks Content-Type)
        // produces: only returns JSON response (checks Accept)
        var saved = productService.save(product);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }
}

@Configuration
public class JacksonConfig {

    @Bean
    public ObjectMapper objectMapper() {
        var mapper = new ObjectMapper();
        // Include non-null fields only (don't serialize null values)
        mapper.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        // Use snake_case for JSON field names instead of camelCase
        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);
        // Write dates as "2024-01-15" instead of timestamps
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;
    }
}

@RestController
class UserController {
    @GetMapping("/api/users/{id}")
    public User getUser(@PathVariable Long id) {
        // This User will be serialized using our custom ObjectMapper
        return new User(id, "john_doe", null); // null email won't appear in JSON
    }
}

record User(Long id, String username, String email) {}

@RestController
@RequestMapping("/api/files")
public class FileController {

    @GetMapping(value = "/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
    public FileMetadata getFileInfo(@PathVariable String id) {
        return new FileMetadata(id, "document.pdf", 2048000L);
    }

    @PostMapping(
        value = "/upload",
        consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
        produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<FileMetadata> uploadFile(
        @RequestParam("file") MultipartFile file
    ) {
        // consumes checks Content-Type: multipart/form-data
        var metadata = fileService.save(file);
        return ResponseEntity.ok(metadata);
    }

    @GetMapping(value = "/{id}/download", produces = MediaType.APPLICATION_OCTET_STREAM_VALUE)
    public ResponseEntity<byte[]> downloadFile(@PathVariable String id) {
        var fileData = fileService.getFileBytes(id);
        return ResponseEntity.ok()
            .header("Content-Disposition", "attachment; filename=\"file.pdf\"")
            .body(fileData);
    }
}

record FileMetadata(String id, String filename, Long size) {}

var restTemplate = new RestTemplate();
var headers = new HttpHeaders();

// Content-Type: what format am I sending?
headers.setContentType(MediaType.APPLICATION_JSON);

// Accept: what format do I want back?
headers.setAccept(List.of(MediaType.APPLICATION_XML));

var order = new Order(null, "Laptop", 1299.99);
var request = new HttpEntity<>(order, headers);

// Sends JSON (Content-Type), expects XML back (Accept)
var response = restTemplate.postForEntity(
    "http://localhost:8080/api/orders",
    request,
    Order.class
);

// Server sees Content-Type: application/json -> deserializes request as JSON
// Server sees Accept: application/xml -> serializes response as XML
